// Python `str` primitives that bech32's decoder depends on.
//
// `bech32_decode` inspects its input one code point at a time and compares the
// string against its own `lower()`/`upper()` forms, so these helpers reproduce
// those exact semantics rather than approximating them.

/**
 * Ordinals of a string, iterated the way Python iterates a `str`:
 * one entry per code point, not per UTF-16 unit.
 */
export function codePoints(text) {
  const points = [];
  for (const char of text) {
    points.push(char.codePointAt(0));
  }
  return points;
}

/** Python's `not any(ord(x) < 33 or ord(x) > 126 for x in text)`. */
export function isPrintableAsciiRange(text) {
  for (const char of text) {
    const point = char.codePointAt(0);
    if (point < 33 || point > 126) {
      return false;
    }
  }
  return true;
}

/**
 * Python's `text.lower() != text and text.upper() != text`.
 *
 * A string with no cased characters at all (e.g. "1231PQYPQA3AQ5Z" has none in
 * its digits, but its letters are all upper) is *not* mixed case, which is why
 * both halves of the conjunction matter. Callers reject non-ASCII input first,
 * so ASCII case mapping is the only behaviour exercised here.
 */
export function isMixedCase(text) {
  return text.toLowerCase() !== text && text.toUpperCase() !== text;
}
