// Coverage probe: how many corpus entries make the REFERENCE print something?
import { readFileSync } from 'node:fs';
import { spawn } from 'node:child_process';

const EXE = '/workspace/dataset/test12_executable';
const corpus = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const LIMIT = 48;
let idx = 0;
let nonEmpty = 0;
let empty = 0;
let nonZeroExit = 0;
const samples = [];

function runOne(argv) {
  return new Promise((resolve) => {
    const p = spawn(EXE, argv, { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    p.stdout.on('data', (d) => { out += d; });
    p.stderr.on('data', (d) => { err += d; });
    p.on('close', (code) => resolve({ out, err, code }));
  });
}

async function worker() {
  while (idx < corpus.length) {
    const i = idx++;
    const r = await runOne(corpus[i]);
    if (r.code !== 0) nonZeroExit++;
    if (r.out.length > 0) {
      nonEmpty++;
      if (samples.length < 10) samples.push([corpus[i], r.out.split('\n')[0]]);
    } else empty++;
  }
}

await Promise.all(Array.from({ length: LIMIT }, worker));
console.log(`total=${corpus.length} printed=${nonEmpty} silent=${empty} nonZeroExit=${nonZeroExit}`);
for (const s of samples) console.log(JSON.stringify(s));

// Generator for the "checksum-tamper" corpus.
