  const per = Math.ceil(arr.length / count);
  for (let i = 0; i < count; i += 1) {
    writeFileSync(`/tmp/corpus/${prefix}${i}.json`, `${JSON.stringify(arr.slice(i * per, (i + 1) * per))}\n`);
